const one = (parameters: readonly AbiParameter[]): AbiParameter => {
  const [first] = parameters;
  if (!first) throw new Error('no parameter');
  return first;
};

/** SpecTypes.BoxSpec as one ABI parameter: `BoxSpec` logs carry `abi.encode(spec)`. */
export const boxSpecV2Parameter: AbiParameter = one(parseAbiParameters(['BoxSpec spec', STRUCTS.spec, STRUCTS.pricing, STRUCTS.side, STRUCTS.branch, STRUCTS.addOn]));
export const boxRecordV2Parameter: AbiParameter = one(parseAbiParameters(['BoxRecordV2 record', STRUCTS.boxRecord]));
export const listingRecordV2Parameter: AbiParameter = one(parseAbiParameters(['ListingRecord listing', STRUCTS.listing, STRUCTS.qParameters]));

/** The params tuples of RecipeTypes.sol the indexer decodes (canonical: abi.encode of the members as a list). */
export const PARAMS_V2 = Object.freeze({
  ruleSplit: parseAbiParameters('address impl, bytes32 codeHash, uint16 defaultBps, uint16 minBps, uint16 maxBps, bytes cfg'),
  plugInLeg: parseAbiParameters('address impl, bytes32 codeHash, bytes cfg'),
  convertLeg: parseAbiParameters('uint8 how, uint32 listingId, address token, address impl, bytes32 codeHash, bytes cfg'),
  boxDest: parseAbiParameters('uint8 mode, uint8 how, uint8 registryIndex, uint256 boxId, address impl, bytes32 codeHash, bytes cfg'),
  fixedShare: parseAbiParameters('uint16 bpsToA'),
  cap30Days: parseAbiParameters('uint8 preset'),
  holdersDest: parseAbiParameters('uint8 currency'),
  itemsDest: parseAbiParameters('uint8 insidePolicy'),
  humbleAddOn: parseAbiParameters('uint8 preset'),
});
